input.command:
cd ~/.claude/projects && for s in 0e822652-5df5-4397-93c3-31866902b930 30498ad3-70c1-4fec-98e3-bc6603dcb826 18660eb2-7ba0-4cdf-bb30-f4d0c4a28a51 880db2d5-3e74-4f23-a2fb-daa6ac552253; do f=$(find . -name "$s.jsonl" | head -1); echo "== $s $f"; python3 - "$f" <<'EOF'
import json,sys
for line in open(sys.argv[1]):
    d=json.loads(line)
    m=d.get('message') or {}
    c=m.get('content')
    if isinstance(c,list):
        for b in c:
            if isinstance(b,dict) and b.get('type')=='tool_use':
                n=b['name']; i=b['input']
                if n in('Write','Edit','MultiEdit','NotebookEdit'): print(n,i.get('file_path'))
                elif n=='Bash': print('Bash',i.get('command','')[:90].replace('\n',' | '))
                elif n in ('AskUserQuestion','Agent','Task'): print(n, str(i)[:90])
EOF
done

